#include <stdio.h>

enum Color { RED, GREEN, BLUE };

void show(enum Color c) {
    if (c == RED) {
        printf("红色\n");
    } else if (c == GREEN) {
        printf("绿色\n");
    } else {
        printf("蓝色\n");
    }
}

int main(void) {
    show({c1});
    show({c2});
    printf("%d %d\n", {c1}, {c2});
    return 0;
}
